import SwiftUI

// sjCream, sjInk, sjMuted, sjBorder, sjSurface are defined as color assets
// in Assets.xcassets and auto-generated by Xcode — no manual declarations needed.

extension Color {
    static let sjBlue         = Color(red: 0.161, green: 0.475, blue: 0.718) // #2979B7
    static let sjAmber        = sjBlue   // alias — theme color is now blue
    static let sjSpotifyGreen = Color(red: 0.114, green: 0.722, blue: 0.333) // #1DB954
}

extension String {
    // Returns a downscaled cover URL (iTunes 600x600bb / 1200x1200bb → 300x300bb;
    // CAA front-500 → front-250).
    //
    // NOTE: this used to also route CAA/archive.org URLs (~95% of covers) through
    // a caching edge proxy (`/api/img`) to skip CAA's redirect-to-archive.org hop.
    // That proxy returns 502 in production -- archive.org blocks Vercel's
    // datacenter IPs -- so every CAA cover was failing outright instead of just
    // loading slowly (confirmed live 2026-07-08: covers stuck on the placeholder
    // indefinitely, not just delayed). Reverted to direct CAA URLs until the
    // proxy is fixed server-side (see SESSIONS.md 2026-07-06/07-08 cover entries
    // for the planned side-table resolver).
    var thumbnailUrl: String {
        self
            .replacingOccurrences(of: "600x600bb",   with: "300x300bb")
            .replacingOccurrences(of: "1200x1200bb", with: "300x300bb")
            .replacingOccurrences(of: "front-500",   with: "front-250")
    }
}

// MARK: - Shimmer placeholder

private struct ShimmerView: View {
    @State private var phase: CGFloat = 0

    var body: some View {
        GeometryReader { geo in
            Color.sjBorder
                .overlay(
                    Rectangle()
                        .fill(LinearGradient(
                            colors: [.clear, .white.opacity(0.28), .clear],
                            startPoint: .leading,
                            endPoint: .trailing
                        ))
                        .frame(width: geo.size.width * 0.55)
                        .offset(x: (geo.size.width * 1.55) * phase - geo.size.width * 0.55)
                )
                .clipped()
        }
        .onAppear {
            withAnimation(.linear(duration: 1.1).repeatForever(autoreverses: false)) {
                phase = 1
            }
        }
    }
}

// MARK: - Shared cover image component

/// Drop-in replacement for AsyncImage on release covers.
/// Applies thumbnailUrl downsizing, shows an animated shimmer while loading,
/// and clips to a rounded rectangle. Set size via .frame() on the call site.
struct CoverImage: View {
    let url: String?
    var cornerRadius: CGFloat = 10

    var body: some View {
        GeometryReader { geo in
            CachedImage(url: URL(string: url?.thumbnailUrl ?? "")) { ShimmerView() }
                .aspectRatio(contentMode: .fill)
                .frame(width: geo.size.width, height: geo.size.height)
                .clipped()
        }
        .clipShape(RoundedRectangle(cornerRadius: cornerRadius))
    }
}
